import { View, Text, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

// Шат 16-д бүтээсэн API. fetchProducts() нь серверийн хариуг Promise-оор буцаана.
const SERVER_PRODUCTS = [
  { id: "p1", name: "Чихэвч", price: 39000 },
  { id: "p2", name: "Гар цаг", price: 129000 },
  { id: "p3", name: "Нарны шил", price: 59000 },
  { id: "p4", name: "Цүнх", price: 89000 },
];
const fetchProducts = () =>
  new Promise((res) => setTimeout(() => res(SERVER_PRODUCTS), 200));

function App() {
  const [products, setProducts] = useState([]);
  // энд бичнэ үү: useEffect дотор fetchProducts()-г дуудаж,
  // ирсэн жагсаалтыг setProducts-д хадгал

  return (
    <View style={styles.s}>
      <Text style={styles.h}>Дэлгүүр ({products.length})</Text>
      {products.map((p) => (
        <Text key={p.id} testID="row" style={styles.row}>{p.name} — {p.price}₮</Text>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 24, gap: 8 },
  h: { fontSize: 20, fontWeight: "bold" },
  row: { fontSize: 16, paddingVertical: 6 },
});

registerRootComponent(App);

import { View, Text, StyleSheet } from "react-native";
import { useState, useEffect } from "react";
import { registerRootComponent } from "expo";

const SERVER_PRODUCTS = [
  { id: "p1", name: "Чихэвч", price: 39000 },
  { id: "p2", name: "Гар цаг", price: 129000 },
  { id: "p3", name: "Нарны шил", price: 59000 },
  { id: "p4", name: "Цүнх", price: 89000 },
];
const fetchProducts = () =>
  new Promise((res) => setTimeout(() => res(SERVER_PRODUCTS), 200));

function App() {
  const [products, setProducts] = useState([]);

  useEffect(() => {
    let alive = true;
    fetchProducts().then((data) => { if (alive) setProducts(data); });
    return () => { alive = false; };
  }, []);

  return (
    <View style={styles.s}>
      <Text style={styles.h}>Дэлгүүр ({products.length})</Text>
      {products.map((p) => (
        <Text key={p.id} testID="row" style={styles.row}>{p.name} — {p.price}₮</Text>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 24, gap: 8 },
  h: { fontSize: 20, fontWeight: "bold" },
  row: { fontSize: 16, paddingVertical: 6 },
});

registerRootComponent(App);
